<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { assignRolePermissions, createRole, listEmployees, listPermissions, listRolePermissions, listRoles, saveEmployee, toggleEmployeeStatus } from '../../api/admin'
import type { Employee, Permission, Role } from '../../api/types'

const employees = ref<Employee[]>([]); const roles = ref<Role[]>([]); const permissions = ref<Permission[]>([]); const loading = ref(false); const employeeKeyword = ref(''); const roleKeyword = ref('')
const employeeDialog = ref(false); const roleDialog = ref(false); const permissionDialog = ref(false); const currentRole = ref<Role | null>(null); const selectedPermissions = ref<number[]>([])
const employeeForm = reactive({ id: undefined as number | undefined, username: '', name: '', phone: '', sex: '1', idNumber: '', password: '', roleIds: [] as number[] })
const roleForm = reactive({ code: '', name: '', description: '' })
const groupLabels: Record<string, string> = { canteen: '食堂', stall: '档口', slot: '取餐时段', dish: '菜品', category: '分类', order: '订单', employee: '员工', role: '角色与权限', report: '报表', shop: '营业状态' }
const filteredEmployees = computed(() => { const kw = employeeKeyword.value.trim(); return kw ? employees.value.filter(e => e.name.includes(kw) || e.username.includes(kw) || (e.phone || '').includes(kw)) : employees.value })
const filteredRoles = computed(() => { const kw = roleKeyword.value.trim(); return kw ? roles.value.filter(r => r.name.includes(kw) || r.code.includes(kw)) : roles.value })
const groupedPermissions = computed(() => { const map = new Map<string, Permission[]>(); for (const p of permissions.value) { const key = p.code.split(':')[0]; if (!map.has(key)) map.set(key, []); map.get(key)!.push(p) } return [...map.entries()].map(([key, list]) => ({ key, label: groupLabels[key] || key, list })) })

async function load() { loading.value = true; try { const [e, r, p] = await Promise.all([listEmployees(), listRoles(), listPermissions()]); employees.value = e.records || []; roles.value = r; permissions.value = p } catch (error) { ElMessage.error((error as Error).message) } finally { loading.value = false } }
function addEmployee() { Object.assign(employeeForm, { id: undefined, username: '', name: '', phone: '', sex: '1', idNumber: '', password: '', roleIds: [] }); employeeDialog.value = true }
function editEmployee(row: Employee) { Object.assign(employeeForm, { id: row.id, username: row.username, name: row.name, phone: row.phone || '', sex: row.sex || '1', idNumber: row.idNumber || '', password: '', roleIds: row.roles?.map(r => r.id) || [] }); employeeDialog.value = true }
async function submitEmployee() { if (!employeeForm.username.trim() || !employeeForm.name.trim() || !employeeForm.phone.trim()) return ElMessage.warning('请填写账号、姓名和手机号'); try { await saveEmployee({ ...employeeForm }); ElMessage.success(employeeForm.id ? '员工信息已更新' : '员工已新增'); employeeDialog.value = false; await load() } catch (error) { ElMessage.error((error as Error).message) } }
async function changeStatus(row: Employee) { try { await toggleEmployeeStatus(row.id, row.status ? 0 : 1); ElMessage.success(row.status ? '员工账号已停用' : '员工账号已启用'); await load() } catch (error) { ElMessage.error((error as Error).message) } }
function addRole() { Object.assign(roleForm, { code: '', name: '', description: '' }); roleDialog.value = true }
async function submitRole() { if (!roleForm.code.trim() || !roleForm.name.trim()) return ElMessage.warning('请填写角色编码和名称'); try { await createRole({ ...roleForm, permissionIds: [] }); ElMessage.success('角色已创建，请继续分配权限'); roleDialog.value = false; await load() } catch (error) { ElMessage.error((error as Error).message) } }
async function openPermissions(role: Role) { currentRole.value = role; try { selectedPermissions.value = await listRolePermissions(role.id); permissionDialog.value = true } catch (error) { ElMessage.error((error as Error).message) } }
async function submitPermissions() { if (!currentRole.value) return; try { await assignRolePermissions(currentRole.value.id, selectedPermissions.value); ElMessage.success('角色权限已更新'); permissionDialog.value = false } catch (error) { ElMessage.error((error as Error).message) } }
onMounted(load)
</script>
<template><div v-loading="loading"><div class="page-card"><div class="page-header"><div><h2 class="page-title">员工与权限</h2><p class="page-subtitle">维护员工账号、角色分配和角色权限点。</p></div></div><div class="page-actionbar"><div class="query-area"><el-input v-model="employeeKeyword" placeholder="搜索姓名、账号或手机号" clearable style="width:260px" /><span class="muted">共 {{ filteredEmployees.length }} 个员工</span></div><div class="action-area"><el-button type="primary" @click="addEmployee">新增员工</el-button></div></div><el-table :data="filteredEmployees" stripe><el-table-column prop="id" label="ID" width="65" /><el-table-column prop="name" label="姓名" width="90" /><el-table-column prop="username" label="账号" width="110" /><el-table-column prop="phone" label="联系电话" width="130" /><el-table-column label="角色" min-width="190"><template #default="{ row }"><el-tag v-for="role in row.roles" :key="role.id" size="small" effect="plain" class="role-tag">{{ role.name }}</el-tag><span v-if="!row.roles?.length" class="muted">未分配</span></template></el-table-column><el-table-column label="状态" width="85"><template #default="{ row }"><el-tag :type="row.status ? 'success' : 'info'">{{ row.status ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="210"><template #default="{ row }"><el-button text type="primary" @click="editEmployee(row)">编辑</el-button><el-button text :type="row.status ? 'warning' : 'success'" @click="changeStatus(row)">{{ row.status ? '停用' : '启用' }}</el-button></template></el-table-column></el-table></div><div class="page-card role-panel"><div class="page-header"><div><h3 class="section-title">角色定义</h3><p class="page-subtitle">角色权限变更后，下一次请求生效。</p></div></div><div class="page-actionbar"><div class="query-area"><el-input v-model="roleKeyword" placeholder="搜索角色名称或编码" clearable style="width:240px" /><span class="muted">共 {{ filteredRoles.length }} 个角色</span></div><div class="action-area"><el-button type="primary" plain @click="addRole">新增角色</el-button></div></div><el-table :data="filteredRoles" stripe><el-table-column prop="code" label="角色编码" width="140" /><el-table-column prop="name" label="角色名称" width="140" /><el-table-column prop="description" label="职责说明" min-width="240" /><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="120"><template #default="{ row }"><el-button text type="primary" @click="openPermissions(row)">分配权限</el-button></template></el-table-column></el-table></div>
<el-dialog v-model="employeeDialog" :title="employeeForm.id ? '编辑员工' : '新增员工'" width="560px"><el-form label-position="top"><el-row :gutter="12"><el-col :span="12"><el-form-item label="登录账号"><el-input v-model="employeeForm.username" :disabled="!!employeeForm.id" /></el-form-item></el-col><el-col :span="12"><el-form-item label="姓名"><el-input v-model="employeeForm.name" /></el-form-item></el-col></el-row><el-row :gutter="12"><el-col :span="12"><el-form-item label="手机号"><el-input v-model="employeeForm.phone" maxlength="11" /></el-form-item></el-col><el-col :span="12"><el-form-item label="性别"><el-radio-group v-model="employeeForm.sex"><el-radio value="1">男</el-radio><el-radio value="0">女</el-radio></el-radio-group></el-form-item></el-col></el-row><el-form-item label="身份证号"><el-input v-model="employeeForm.idNumber" maxlength="18" /></el-form-item><el-form-item label="密码"><el-input v-model="employeeForm.password" type="password" show-password :placeholder="employeeForm.id ? '留空表示不修改密码' : '留空则使用默认密码 123456'" /></el-form-item><el-form-item label="所属角色"><el-select v-model="employeeForm.roleIds" multiple placeholder="请选择角色" style="width:100%"><el-option v-for="role in roles" :key="role.id" :label="role.name" :value="role.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="employeeDialog=false">取消</el-button><el-button type="primary" @click="submitEmployee">保存</el-button></template></el-dialog>
<el-dialog v-model="roleDialog" title="新增角色" width="460px"><el-form label-position="top"><el-form-item label="角色编码"><el-input v-model="roleForm.code" placeholder="例如 KITCHEN_MANAGER" /></el-form-item><el-form-item label="角色名称"><el-input v-model="roleForm.name" placeholder="例如 档口主管" /></el-form-item><el-form-item label="职责说明"><el-input v-model="roleForm.description" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="roleDialog=false">取消</el-button><el-button type="primary" @click="submitRole">创建</el-button></template></el-dialog>
<el-dialog v-model="permissionDialog" :title="`分配权限：${currentRole?.name || ''}`" width="760px"><div class="permission-grid"><div v-for="group in groupedPermissions" :key="group.key" class="permission-group"><strong>{{ group.label }}</strong><el-checkbox-group v-model="selectedPermissions"><el-checkbox v-for="permission in group.list" :key="permission.id" :value="permission.id">{{ permission.name }}</el-checkbox></el-checkbox-group></div></div><template #footer><el-button @click="permissionDialog=false">取消</el-button><el-button type="primary" @click="submitPermissions">保存权限</el-button></template></el-dialog></div></template>
<style scoped>.role-panel{margin-top:14px}.section-title{margin:0}.role-tag{margin:2px 4px 2px 0}.permission-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;max-height:520px;overflow:auto}.permission-group{border:1px solid #e1e8e4;padding:12px;border-radius:4px}.permission-group strong{display:block;font-size:13px;color:#31534a;margin-bottom:8px}.permission-group :deep(.el-checkbox-group){display:grid;grid-template-columns:1fr 1fr;gap:3px}.permission-group :deep(.el-checkbox){margin-right:0;height:24px}@media(max-width:700px){.permission-grid{grid-template-columns:1fr}}
</style>
